gmG(){return"\ub9ac\ud3ec\ud2b8 \uc0dd\uc131 LLM\uff08\uc120\ud0dd \uc0ac\ud56d\uff09"},
gox(){return"\uac1c\uc778\uc815\ubcf4\ucc98\ub9ac\ubc29\uce68"},
