gka(){return"\u041d\u0430\u0441\u0442\u0440\u043e\u0439\u043a\u0438 \u043f\u043e\u0434\u043c\u043e\u0434\u0443\u043b\u0435\u0439 \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u0438\u044f (\u0430\u043d\u0441\u0430\u043c\u0431\u043b\u044c)"},
